<?php
declare(strict_types=1);

/*
    filename: install_admin_backup_manager_v002_20260903_011125pm.php
    VERSION: v002
    LAST MODIFIED: 9/3/2026 1:11:25 pm

    PURPOSE:
    - Install unified admin_backup.php manager.
    - Convert existing admin_db_backup.php into guarded admin_backup_db_helper.php.
    - Add guarded admin_backup_files_helper.php.
    - Remove original admin_db_backup.php only after successful install.
    - Provide preflight, apply and rollback.
*/

if (session_status() === PHP_SESSION_NONE) session_start();
require_once $_SERVER['DOCUMENT_ROOT'] . '/config.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/config_mrl.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/class.user.php';
$user_home = new USER();
if (!$user_home->is_logged_in()) { $user_home->redirect('login.php'); exit; }
if (!isAdmin($_SESSION['userSession'] ?? null)) { http_response_code(403); exit('Not authorized.'); }

$root=__DIR__;
$source=$root.'/admin_db_backup.php';
$targetManager=$root.'/admin_backup.php';
$targetDb=$root.'/admin_backup_db_helper.php';
$targetFiles=$root.'/admin_backup_files_helper.php';
$backupBase=$root.'/_migration_backups/admin_backup_manager_v002_20260903_011125pm';
$domainRoot=dirname($root);
$filesBackupDir=$domainRoot.'/_mrl_backups/files';
$action=(string)($_POST['action']??'');
$msg=[];$err=[];
function iab_h($v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function iab_write(string $path,string $b64): bool { $data=base64_decode($b64,true); return $data!==false && file_put_contents($path,$data,LOCK_EX)!==false; }
function iab_zip_timestamp_test(string $workDir): array {
    if (!class_exists('ZipArchive')) return [false,'ZipArchive is not available.'];
    if (!is_dir($workDir) && !@mkdir($workDir,0755,true)) return [false,'Could not create temporary timestamp-test folder.'];
    if (!is_writable($workDir)) return [false,'Timestamp-test folder is not writable.'];

    $token='iab_mtime_'.bin2hex(random_bytes(4));
    $file=$workDir.'/'.$token.'.txt';
    $zipPath=$workDir.'/'.$token.'.zip';
    $entry=$token.'.txt';
    $wanted=time()-7200; if(($wanted%2)!==0)$wanted--;
    $ok=@file_put_contents($file,"MRL timestamp test\n")!==false && @touch($file,$wanted);
    $stored=0;

    if($ok){
        $z=new ZipArchive();
        $res=$z->open($zipPath,ZipArchive::CREATE|ZipArchive::OVERWRITE);
        if($res===true){
            $ok=$z->addFile($file,$entry);
            if($ok && method_exists($z,'setMtimeName')) @ $z->setMtimeName($entry,$wanted);
            $z->close();
        } else $ok=false;
    }
    if($ok){
        $z=new ZipArchive();
        if($z->open($zipPath)===true){
            $st=$z->statName($entry);
            if(is_array($st))$stored=(int)($st['mtime']??0);
            $z->close();
        }
    }
    @unlink($file); @unlink($zipPath);
    $pass=$ok && $stored>0 && abs($stored-$wanted)<=2;
    return [$pass,$pass?'Actual ZIP round-trip retained the source file modification time.':'ZIP round-trip did not retain the source file modification time.'];
}
$payloads=[
    'admin_backup.php' => '',
    'admin_backup_db_helper.php' => '',
    'admin_backup_files_helper.php' => ''
];

$timestampTestDir=$domainRoot.'/_mrl_backups/.installer_test';
[$timestampOk,$timestampDetail]=class_exists('ZipArchive') ? iab_zip_timestamp_test($timestampTestDir) : [false,'ZipArchive is not available.'];
if(is_dir($timestampTestDir)) @rmdir($timestampTestDir);

$pre=[
 ['Current admin_db_backup.php exists',is_file($source),'Required','Source page to preserve and convert into the DB helper.'],
 ['public_html writable',is_writable($root),'Required','Needed to create the manager/helper files and installer rollback copy.'],
 ['ZipArchive available',class_exists('ZipArchive'),'Required','Required to build the file-backup ZIP.'],
 ['File timestamp round-trip',$timestampOk,'Required',$timestampDetail],
 ['ZipArchive setMtimeName API',class_exists('ZipArchive') && method_exists('ZipArchive','setMtimeName'),'Info',method_exists('ZipArchive','setMtimeName')?'Available; timestamps can also be set explicitly.':'Not available on this PHP version; not required because the real ZIP timestamp test above is authoritative.'],
 ['Domain root writable',is_writable($domainRoot),'Required','Needed for /_mrl_backups/files outside public_html.'],
];
$preOk=true; foreach($pre as $p) if($p[2]==='Required' && !$p[1]) $preOk=false;

if($action==='apply' && $preOk){
    if(!is_dir($backupBase) && !@mkdir($backupBase,0755,true)) $err[]='Could not create installer backup folder.';
    if(!$err){
        foreach([$source,$targetManager,$targetDb,$targetFiles] as $p){ if(is_file($p) && !@copy($p,$backupBase.'/'.basename($p))) $err[]='Could not back up '.basename($p); }
    }
    if(!$err && !is_dir($filesBackupDir) && !@mkdir($filesBackupDir,0755,true)) $err[]='Could not create outside-public_html files backup folder.';
    if(!$err){
        foreach($payloads as $name=>$b64){ if(!iab_write($root.'/'.$name,$b64)) $err[]='Could not write '.$name; }
    }
    if(!$err){
        foreach([$targetManager,$targetDb,$targetFiles] as $p){ $out=[];$rc=0; @exec('php -l '.escapeshellarg($p).' 2>&1',$out,$rc); if($rc!==0) $err[]='PHP syntax failed for '.basename($p).': '.implode(' ',$out); }
    }
    if(!$err){
        if(!@unlink($source)) $err[]='New files installed, but could not remove original admin_db_backup.php.';
        else $msg[]='INSTALL COMPLETE — admin_backup.php is now the Backup Manager front door.';
    }
}

if($action==='rollback'){
    $old=$backupBase.'/admin_db_backup.php';
    if(!is_file($old)) $err[]='Rollback source admin_db_backup.php not found.';
    else{
        foreach([$targetManager,$targetDb,$targetFiles] as $p) if(is_file($p)) @unlink($p);
        if(@copy($old,$source)) $msg[]='ROLLBACK COMPLETE — original admin_db_backup.php restored.'; else $err[]='Could not restore original admin_db_backup.php.';
    }
}
?>
